do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int; isnew boolean;
begin
insert into public.companies(ticker,name,segment,size_tier,is_seed,is_hero) values ($q$UBER$q$,$q$Uber Technologies$q$,$q$consumer$q$,$q$large$q$,true,true),($q$AAPL$q$,$q$Apple$q$,$q$consumer$q$,$q$large$q$,true,false),($q$META$q$,$q$Meta Platforms$q$,$q$consumer$q$,$q$large$q$,true,false),($q$MSFT$q$,$q$Microsoft$q$,$q$business$q$,$q$large$q$,true,false),($q$PLTR$q$,$q$Palantir Technologies$q$,$q$business$q$,$q$large$q$,true,false),($q$NVDA$q$,$q$NVIDIA$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$TSM$q$,$q$Taiwan Semiconductor Manufacturing$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$AMD$q$,$q$Advanced Micro Devices$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$DASH$q$,$q$DoorDash$q$,$q$consumer$q$,$q$mid$q$,true,false),($q$NET$q$,$q$Cloudflare$q$,$q$business$q$,$q$mid$q$,true,false),($q$CRWV$q$,$q$CoreWeave$q$,$q$infrastructure$q$,$q$mid$q$,true,true),($q$CBRS$q$,$q$Cerebras Systems$q$,$q$infrastructure$q$,$q$mid$q$,true,false),($q$NBIS$q$,$q$Nebius Group$q$,$q$infrastructure$q$,$q$mid$q$,true,false),($q$LYFT$q$,$q$Lyft$q$,$q$consumer$q$,$q$small$q$,true,true),($q$APLD$q$,$q$Applied Digital$q$,$q$infrastructure$q$,$q$small$q$,true,false),($q$AMZN$q$,$q$Amazon$q$,$q$consumer$q$,$q$large$q$,true,false),($q$GOOGL$q$,$q$Alphabet$q$,$q$consumer$q$,$q$large$q$,true,false),($q$TSLA$q$,$q$Tesla$q$,$q$consumer$q$,$q$large$q$,true,false),($q$ORCL$q$,$q$Oracle$q$,$q$business$q$,$q$large$q$,true,false),($q$INTC$q$,$q$Intel$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$LCID$q$,$q$Lucid$q$,$q$consumer$q$,$q$small$q$,true,false),($q$LIME$q$,$q$Lime$q$,$q$consumer$q$,$q$small$q$,true,false),($q$CART$q$,$q$Instacart$q$,$q$consumer$q$,$q$mid$q$,true,false),($q$GRAB$q$,$q$Grab$q$,$q$consumer$q$,$q$mid$q$,true,false),($q$AUR$q$,$q$Aurora$q$,$q$business$q$,$q$small$q$,true,false) on conflict (ticker) do update set is_seed=true, segment=excluded.segment, size_tier=excluded.size_tier, is_hero=excluded.is_hero;
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$Hobbes$q$,$q$private_company$q$),($q$Music Learning Services Limited$q$,$q$private_company$q$),($q$Stripe$q$,$q$private_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$AWS and Google Cloud provide us with computing and storage capacity pursuant to agreements that continue until terminated by either party.$q$),(2,$q$Any failure, disruption or interference with our use of hosted cloud computing services and systems provided by third-parties, like AWS or Google Cloud, could adversely impact our business, financial condition or results of operations.$q$),(3,$q$For example, in July 2025, we completed the acquisition of the team behind NextBeat through the purchase of Music Learning Services Limited, a U.K.-based entity, and in July 2024, we completed the acquisition of Hobbes, an animation and motion design studio based in Detroit, Michigan.$q$),(4,$q$In the twelve months ended December 31, 2025, we derived 62% of our revenue and 61% of our total bookings from the Apple App Store, and 20% of our revenue and 21% of our total bookings from the Google Play Store.$q$),(5,$q$Many large companies, such as Amazon, Facebook and Google, invest significantly in data analytics to make their websites and platforms more attractive to advertisers.$q$),(6,$q$The top three service providers, Apple, Google, and Stripe accounted for$q$),(7,$q$We depend on Apple and Google approving our mobile applications to be distributed on their respective platforms.$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$supplies$q$,$q$Apple$q$,$q$DUOL$q$,$q${7,4,6}$q$::int[],$q${risk_factors,risk_factors,notes}$q$::text[],null,null,null,null),(2,$q$supplies$q$,$q$Alphabet$q$,$q$DUOL$q$,$q${7,4,6}$q$::int[],$q${risk_factors,risk_factors,notes}$q$::text[],null,null,null,null),(3,$q$supplies$q$,$q$Amazon$q$,$q$DUOL$q$,$q${1,2}$q$::int[],$q${risk_factors,risk_factors}$q$::text[],null,null,null,null),(4,$q$competes$q$,$q$DUOL$q$,$q$Amazon$q$,$q${5}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(5,$q$competes$q$,$q$DUOL$q$,$q$Meta Platforms$q$,$q${5}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(6,$q$competes$q$,$q$DUOL$q$,$q$Alphabet$q$,$q${5}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(7,$q$acquires$q$,$q$DUOL$q$,$q$Music Learning Services Limited$q$,$q${3}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(8,$q$acquires$q$,$q$DUOL$q$,$q$Hobbes$q$,$q${3}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(9,$q$supplies$q$,$q$Stripe$q$,$q$DUOL$q$,$q${6}$q$::int[],$q${notes}$q$::text[],null,null,null,null);
create or replace function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$Uber$q$ then ticker=$q$UBER$q$ when $q$Alphabet$q$ then ticker=$q$GOOGL$q$ when $q$Microsoft$q$ then ticker=$q$MSFT$q$ when $q$Apple$q$ then ticker=$q$AAPL$q$ when $q$Amazon$q$ then ticker=$q$AMZN$q$ when $q$Meta Platforms$q$ then ticker=$q$META$q$ when $q$Duolingo$q$ then ticker=$q$DUOL$q$ when $q$DUOL$q$ then ticker=$q$DUOL$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,cost_usd,status,review_status) values ('filings_extraction','live',$q$DUOL live lookup queue 4 (processed by Claude Code)$q$,'claude-sonnet-5-5 via Claude Code session',0.6411,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; isnew := false; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,trust_status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else '2025-12-31'::date end,'sec_filing',$q$live$q$,$q$live_generated$q$,run_id,'2025-12-31',r.note) returning id into rid; isnew := true; end if; if isnew then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,$q$https://www.sec.gov/Archives/edgar/data/1562088/000162828026012494/duol-20251231.htm$q$,r.sec[k],t,true,$q$2026-02-27$q$ from _q where i=r.qs[k]; end loop; end if; end loop;
update public.lookup_queue set status='done', step='Done', links_found=(select count(*) from _e), run_id=(select max(id) from public.agent_runs), finished_at=now(), company_id=pg_temp.nid($q$DUOL$q$) where id=4;
end $do$;
